'use strict';
function initFrisbeeAI({requestEdit,onDraft,drawFrame,toast,prepareCreation}){
 const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let generated=null,generation=null,chatRequest=null,history=[],turns=new Map(),turnNumber=0;
 const endpoint=path=>new URL('api/ai/'+path,location.href.split('#')[0]);
 let reviewSignature=null,reviewQuestions=false,reviewBaseline='',creationMode='ai',creationPage='setup',pageSerial=0,previewIndex=0,aiAvailable=false;
 const settings=()=>({kind:document.querySelector('[data-create-kind][aria-pressed="true"]').dataset.createKind,offense:Number($('#create-offense').value),defense:Number($('#create-defense').value)});
 const sourceSnapshot=()=>JSON.stringify({...settings(),description:$('#ai-description').value});
 const pageIds={setup:'creation-setup',description:'creation-description',review:'ai-review-section',preview:'creation-preview'},pageOrder=['setup','description','review','preview'];
 function progress(){const labels=creationMode==='ai'?['设置','描述','核对','预览']:['设置','战术板'];$('#creation-progress').style.setProperty('--creation-steps',labels.length);$('#creation-progress').innerHTML=labels.map((text,i)=>'<span class="'+(i===pageOrder.indexOf(creationPage)?'active':i<pageOrder.indexOf(creationPage)?'complete':'')+'"'+(i===pageOrder.indexOf(creationPage)?' aria-current="step"':'')+'><i>'+(i+1)+'</i>'+text+'</span>').join('');$('#creation-back').hidden=creationPage==='setup';$('#creation-title').textContent={setup:'选择创建方式',description:'描述你的想法',review:'核对角色与顺序',preview:'检查战术预览'}[creationPage];$('#creation-kicker').textContent=creationMode==='ai'?'Tiga · AI 辅助创建':'Tiga · 手动创建';}
 function page(name,direction=1){const old=$('#'+pageIds[creationPage]),next=$('#'+pageIds[name]);if(!next)return;const serial=++pageSerial;document.querySelectorAll('.creation-page').forEach(el=>{el.getAnimations?.().forEach(a=>a.cancel());if(el!==old&&el!==next){el.hidden=true;el.inert=true;}});creationPage=name;if(old!==next)old.inert=true;next.inert=false;next.hidden=false;next.scrollTop=0;progress();if(old!==next&&!window.matchMedia('(prefers-reduced-motion:reduce)').matches&&next.animate){old.style.zIndex='1';next.style.zIndex='2';old.animate([{transform:'translateX(0)',opacity:1},{transform:'translateX('+(-12*direction)+'%)',opacity:0}],{duration:180,easing:'ease-out'});next.animate([{transform:'translateX('+(18*direction)+'%)',opacity:0},{transform:'translateX(0)',opacity:1}],{duration:230,easing:'cubic-bezier(.2,.7,.2,1)'}).finished.then(()=>{if(serial===pageSerial)old.hidden=true;}).catch(()=>{});}else if(old!==next)old.hidden=true;$('#creation-title').setAttribute('tabindex','-1');$('#creation-title').focus({preventScroll:true});}
 function clearGenerated(){generated=null;$('#ai-plan-preview').innerHTML='';$('#ai-open-draft').hidden=true;}
 function confirmState(){const valid=reviewSignature===sourceSnapshot(),changed=$('#ai-formal-description').value.trim()!==reviewBaseline.trim();$('#ai-confirm-generate').disabled=!!generation||!valid||!$('#ai-formal-description').value.trim()||(reviewQuestions&&!changed);}
 function mode(value){creationMode=value==='ai'&&aiAvailable?'ai':'manual';$('#ai-create-btn').setAttribute('aria-pressed',String(creationMode==='ai'));$('#manual-create-btn').setAttribute('aria-pressed',String(creationMode==='manual'));$('#create-offense').min=creationMode==='ai'?'1':'0';$('#create-name-label').hidden=creationMode==='ai';$('#preset-label').hidden=creationMode==='ai'||settings().kind==='drill';$('#creation-start').textContent=creationMode==='ai'?'下一步：描述想法 →':'进入战术板 →';progress();}
 function busy(on){for(const id of ['create-offense','create-defense','create-name','create-preset','ai-description','ai-formal-description','ai-generate-btn','creation-back','creation-start','manual-create-btn'])$('#'+id).disabled=on;document.querySelectorAll('[data-create-kind]').forEach(el=>el.disabled=on);$('#ai-create-btn').disabled=on||!aiAvailable;confirmState();}
 function openSetup(value='ai'){++pageSerial;document.querySelectorAll('.creation-page').forEach(el=>el.getAnimations?.().forEach(a=>a.cancel()));clearGenerated();reviewSignature=null;$('#ai-tactic-result').textContent='';document.querySelectorAll('.creation-page').forEach(el=>{el.hidden=true;el.inert=true;});creationPage='setup';mode(value);$('#creation-setup').hidden=false;$('#creation-setup').inert=false;if(!$('#create-dialog').open)$('#create-dialog').showModal();$('#creation-title').focus({preventScroll:true});}
 function showGeneration(){requestEdit(()=>{prepareCreation?.();openSetup('ai');});}
 $('#ai-new-btn').onclick=showGeneration;$('#ai-create-btn').onclick=()=>mode('ai');$('#manual-create-btn').onclick=()=>mode('manual');
 document.querySelectorAll('[data-create-kind]').forEach(el=>el.addEventListener('click',()=>mode(creationMode)));
 MobileUI.registerBack('create-dialog',()=>{if(generation){generation.abort();return false;}if(creationPage!=='setup'){const index=pageOrder.indexOf(creationPage);page(pageOrder[index-1],-1);return false;}$('#create-dialog').close();return true;});
 $('#create-cancel').onclick=()=>$('#create-dialog').close();$('#create-dialog').addEventListener('close',()=>generation?.abort());
 $('#creation-back').onclick=()=>{if(generation)return;$('#ai-tactic-result').textContent='';const index=pageOrder.indexOf(creationPage);if(index>0)page(pageOrder[index-1],-1);};
 for(const id of ['create-offense','create-defense','create-preset'])$('#'+id).addEventListener('input',()=>{if(reviewSignature!==null){clearGenerated();confirmState();}});
 $('#ai-description').addEventListener('input',()=>{if(reviewSignature!==null){clearGenerated();confirmState();}});
 $('#ai-formal-description').addEventListener('input',()=>{clearGenerated();$('#ai-tactic-result').textContent='说明已修改，将按你确认的这一版生成。';confirmState();});
 function showQuestions(questions){$('#ai-review-questions').hidden=!questions.length;$('#ai-review-questions').innerHTML=questions.length?'<strong>先补充以下信息，再确认</strong><ul>'+questions.map(q=>'<li>'+escape(q)+'</li>').join('')+'</ul>':'';}
 async function generationRequest(path,payload){const controller=new AbortController();generation=controller;const timer=setTimeout(()=>controller.abort(),140000);busy(true);try{const response=await fetch(endpoint(path),{method:'POST',credentials:'same-origin',signal:controller.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();if(!response.ok)throw Error(data.error||'AI 暂时不可用，请稍后重试。');return data;}finally{clearTimeout(timer);generation=null;busy(false);}}
 $('#ai-tactic-form').onsubmit=async event=>{event.preventDefault();if(generation)return;if(reviewSignature===sourceSnapshot()&&$('#ai-formal-description').value.trim()){page('review');return;}clearGenerated();reviewSignature=null;const signature=sourceSnapshot();$('#ai-tactic-result').textContent='正在整理角色与传跑顺序…';try{const data=await generationRequest('outline',{...settings(),description:$('#ai-description').value});if(data.status!=='review'||!data.formal_description)throw Error('未收到完整说明，请重试。');reviewSignature=signature;reviewQuestions=!!data.questions?.length;reviewBaseline=data.formal_description;$('#ai-formal-description').value=reviewBaseline;showQuestions(data.questions||[]);$('#ai-tactic-result').textContent='';confirmState();page('review');}catch(error){$('#ai-tactic-result').textContent=error.name==='AbortError'?'整理已停止或超时，描述仍保留。':error.message;confirmState();}};
 function preview(index=0){if(!generated)return;previewIndex=Math.max(0,Math.min(generated.frames.length-1,index));const f=generated.frames[previewIndex];$('#ai-plan-preview').innerHTML='<div class="creation-preview-heading"><h3>'+escape(generated.name)+'</h3><span>'+generated.frames[0].players.length+' 人 · '+generated.frames.length+' 步 · '+(generated.markers||[]).length+' 个角标</span></div><div class="creation-preview-canvas">'+drawFrame(f,generated.markers||[])+'</div><div class="creation-preview-controls"><button type="button" id="ai-preview-prev" class="quiet-btn" aria-label="预览上一步" '+(previewIndex===0?'disabled':'')+'>←</button><span>'+(previewIndex+1)+' / '+generated.frames.length+'</span><button type="button" id="ai-preview-next" class="quiet-btn" aria-label="预览下一步" '+(previewIndex===generated.frames.length-1?'disabled':'')+'>→</button></div><h4>'+escape(f.name)+'</h4><p class="creation-step-notes">'+escape(f.notes)+'</p><details class="creation-drawing-notes"><summary>说明与绘图约定</summary><p>'+escape(generated.summary)+'</p>'+(generated.frames[0].notes?'<p>'+escape(generated.frames[0].notes)+'</p>':'')+'</details>';$('#ai-preview-prev').onclick=()=>preview(previewIndex-1);$('#ai-preview-next').onclick=()=>preview(previewIndex+1);}
 $('#ai-confirm-generate').onclick=async()=>{if(generation||reviewSignature!==sourceSnapshot())return;const description=$('#ai-formal-description').value.trim();if(!description)return;clearGenerated();$('#ai-tactic-result').textContent='正在按确认的说明画图并检查布局…';try{const data=await generationRequest('tactic',{...settings(),description,confirmed:true});if(data.status==='clarify'){reviewQuestions=true;reviewBaseline=description;showQuestions(data.questions||[]);$('#ai-tactic-result').textContent='请补充说明中的待确认信息。';confirmState();return;}if(data.status!=='ready'||!data.tactic)throw Error('没有收到完整草稿，请重试。');generated=data.tactic;showQuestions([]);$('#ai-tactic-result').textContent='';preview();$('#ai-open-draft').hidden=false;page('preview');}catch(error){$('#ai-tactic-result').textContent=error.name==='AbortError'?'生成已停止或超时，确认的说明仍保留。':error.message;}};
 $('#ai-open-draft').onclick=()=>{if(!generated)return;const draft=generated;$('#create-dialog').close();onDraft(draft);};
 const sheet=$('#ai-chat-dialog'),sheetToggle=$('#ai-rules-btn');let sheetOpen=false,sheetHideTimer=0;
 function syncPhoneSheet(){const phone=MobileUI.isPhone();document.body.classList.toggle('phone-ai-open',phone&&sheetOpen);document.querySelector('.workspace').inert=phone&&sheetOpen;$('#ai-chat-close').setAttribute('aria-label',phone?'返回规则':'收起 AI 问答');if(phone&&sheetOpen)MobileUI.enter('rules-ai',()=>{closeSheet(false);return true;});}
 function fitSheet(){syncPhoneSheet();const viewport=window.visualViewport,mobile=window.matchMedia('(max-width:600px)').matches;sheet.style.setProperty('--ai-visual-height',(viewport?.height||window.innerHeight)+'px');sheet.style.setProperty('--ai-keyboard-offset',(mobile&&viewport?Math.max(0,window.innerHeight-viewport.height-viewport.offsetTop):0)+'px');}
 function closeSheet(returnFocus=true){if(!sheetOpen)return;sheetOpen=false;syncPhoneSheet();MobileUI.leave('rules-ai');sheet.classList.remove('is-open');sheet.inert=true;sheet.setAttribute('aria-hidden','true');sheetToggle.setAttribute('aria-expanded','false');if(returnFocus&&!$('#rules-header-actions').hidden)sheetToggle.focus({preventScroll:true});clearTimeout(sheetHideTimer);sheetHideTimer=setTimeout(()=>{if(!sheetOpen)sheet.hidden=true;},230);}
 function openSheet(){clearTimeout(sheetHideTimer);sheetOpen=true;sheet.hidden=false;sheet.inert=false;sheet.setAttribute('aria-hidden','false');sheetToggle.setAttribute('aria-expanded','true');fitSheet();requestAnimationFrame(()=>{if(!sheetOpen)return;void sheet.offsetHeight;sheet.classList.add('is-open');scrollChat();if(window.matchMedia('(min-width:701px)').matches)$('#ai-question').focus({preventScroll:true});else $('#ai-chat-title').focus({preventScroll:true});});}
 sheetToggle.onclick=()=>sheetOpen?closeSheet():openSheet();$('#ai-chat-close').onclick=()=>closeSheet();
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&sheetOpen&&!document.querySelector('dialog[open]')){event.preventDefault();closeSheet();}});
 new MutationObserver(()=>{if($('#rules-header-actions').hidden)closeSheet(false);}).observe($('#rules-header-actions'),{attributes:true,attributeFilter:['hidden']});
 window.addEventListener('resize',fitSheet);window.visualViewport?.addEventListener('resize',fitSheet);window.visualViewport?.addEventListener('scroll',fitSheet);
 $('#ai-chat-stop').onclick=()=>chatRequest?.abort();
 $('#ai-chat-clear').onclick=()=>{if(chatRequest)return;history=[];turns.clear();$('#ai-messages').innerHTML='';$('#ai-chat-intro').hidden=false;};
 function scrollChat(){const box=$('#ai-chat-scroll');box.scrollTop=box.scrollHeight;}
 function renderSourceButtons(turn){
  const limit=MobileUI.isPhone()?3:8;
  const box=document.querySelector('[data-turn="'+turn.id+'"] .ai-references');
  box.innerHTML=(turn.sources.length?'<span>检索依据</span>'+turn.sources.slice(0,limit).map(s=>'<button data-ai-source="'+turn.id+'" data-ai-citation="'+escape(s.citation)+'">'+escape(s.citation)+'</button>').join('')+(turn.sources.length>limit?'<button data-ai-all-sources="'+turn.id+'">全部 '+turn.sources.length+' 条</button>':''):'')+(turn.visuals.length?'<div class="ai-gesture-row">'+turn.visuals.map(v=>'<button data-ai-visual="'+turn.id+'" data-visual-id="'+escape(v.id)+'"><img src="'+escape(staticAsset(v.image))+'" alt="'+escape(v.title)+'" loading="lazy"><span>'+escape(v.title)+'</span></button>').join('')+'</div>':'');
 }
 function finishAnswer(turn,data){
  const article=document.querySelector('[data-turn="'+turn.id+'"]'),body=article.querySelector('.ai-answer'),state=article.querySelector('.ai-response-status');
  if(turn.answer&&data.grounded){
   const allowed=new Set(turn.sources.map(s=>s.citation));
   let value=escape(turn.answer).replace(/\[([^\[\]\n]{1,40})\]/g,(all,cite)=>allowed.has(cite)?'<button class="ai-inline-cite" data-ai-source="'+turn.id+'" data-ai-citation="'+escape(cite)+'">['+escape(cite)+']</button>':all);
   value=value.replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>');body.innerHTML=value;state.textContent='已附可核对条款 · '+((performance.now()-turn.started)/1000).toFixed(1)+' 秒';
   history.push({role:'user',content:turn.question},{role:'assistant',content:turn.answer.slice(0,2000)});history=history.slice(-4);
  }else if(data.reason==='no_sources'){
   body.textContent=turn.answer||'暂未匹配到相关原文，可用中英文补充动作或输入条款号。';state.textContent='暂未匹配到条款';
  }else if(turn.sources.length&&turn.answer){
   body.textContent='这次回复未通过条款引用校验，已隐藏解释内容。请先核对检索原文，或补充情形后重新提问。';state.textContent='请核对原文';
  }else{body.textContent=turn.answer||'请补充具体情形后再试。';state.textContent='需要补充情形';}
 }
 async function consumeEvents(response,callback){
  const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
  while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});buffer=buffer.replace(/\r\n/g,'\n');if(buffer.length>1048576)throw Error('回复内容过长，请重新提问。');let end;
   while((end=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,end);buffer=buffer.slice(end+2);let event='message',data=[];for(const line of block.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();if(line.startsWith('data:'))data.push(line.slice(5).trimStart());}if(data.length)callback(event,JSON.parse(data.join('\n')));}
  }
 }
 $('#ai-chat-form').onsubmit=async event=>{
  event.preventDefault();if(chatRequest)return;
  const question=$('#ai-question').value.trim();if(!question)return;
  $('#ai-chat-intro').hidden=true;$('#ai-question').value='';if(MobileUI.isPhone())$('#ai-question').blur();const id=String(++turnNumber),turn={id,question,sources:[],visuals:[],answer:'',started:performance.now()};turns.set(id,turn);
  $('#ai-messages').insertAdjacentHTML('beforeend','<article class="ai-user"><p>'+escape(question)+'</p></article><article class="ai-assistant" data-turn="'+id+'"><div class="ai-response-status">正在检索条款…</div><div class="ai-answer" aria-live="polite"></div><div class="ai-references"></div></article>');
  const article=document.querySelector('[data-turn="'+id+'"]'),body=article.querySelector('.ai-answer'),state=article.querySelector('.ai-response-status');
  const controller=new AbortController();chatRequest=controller;const timer=setTimeout(()=>controller.abort(),140000);$('#ai-chat-send').disabled=true;$('#ai-chat-stop').hidden=false;$('#ai-chat-clear').disabled=true;scrollChat();let completed=false;
  try{
   const response=await fetch(endpoint('rules'),{method:'POST',credentials:'same-origin',signal:controller.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify({question,history:history.map(m=>({...m,content:m.content.slice(0,1500)}))})});
   if(!response.ok){const data=await response.json();throw Error(data.error||'AI 暂时不可用。');}
   await consumeEvents(response,(event,data)=>{
    if(event==='sources'){SpeedInfo.ai={sources:performance.now()-turn.started};turn.sources=data.sources||[];turn.visuals=data.visuals||[];renderSourceButtons(turn);state.textContent='已检索 '+turn.sources.length+' 条依据，正在组织回答…';}
    if(event==='delta'){turn.answer+=data.text||'';if(!turn.firstText){turn.firstText=performance.now();SpeedInfo.ai.firstText=turn.firstText-turn.started;}if(!turn.paint)turn.paint=requestAnimationFrame(()=>{turn.paint=0;const box=$('#ai-chat-scroll'),follow=box.scrollHeight-box.scrollTop-box.clientHeight<100;body.textContent=turn.answer;state.textContent='正在回复 · 首字 '+((turn.firstText-turn.started)/1000).toFixed(1)+' 秒';if(follow)scrollChat();});}
    if(event==='done'){SpeedInfo.ai.total=performance.now()-turn.started;cancelAnimationFrame(turn.paint||0);turn.paint=0;finishAnswer(turn,data);completed=true;}
    if(event==='error')throw Error(data.message||'回复中断，请重试。');
   });
   if(!completed)throw Error('回复未完整结束，以上文字尚未通过引用校验。');
  }catch(error){state.textContent=error.name==='AbortError'?'已停止；未完成的文字请以原文核对。':error.message;if(!turn.answer)body.textContent='可以补充信息后重试，或直接使用规则检索。';}
  finally{cancelAnimationFrame(turn.paint||0);if(!completed&&turn.answer)body.textContent=turn.answer;clearTimeout(timer);chatRequest=null;$('#ai-chat-send').disabled=false;$('#ai-chat-stop').hidden=true;$('#ai-chat-clear').disabled=false;}
 };
 document.addEventListener('click',event=>{
  const quick=event.target.closest('[data-ai-question]');if(quick){$('#ai-question').value=quick.dataset.aiQuestion;$('#ai-question').focus();}
  const source=event.target.closest('[data-ai-source],[data-ai-all-sources],[data-ai-read-source]');
  if(source){const turn=turns.get(source.dataset.aiSource||source.dataset.aiAllSources||source.dataset.aiReadSource);if(!turn)return;const selected=turn.sources.find(s=>s.citation===source.dataset.aiCitation);let list=turn.sources;
   if(selected&&MobileUI.isPhone()&&!source.dataset.aiReadSource){
    const article=document.querySelector('[data-turn="'+turn.id+'"]');let preview=article.querySelector('.ai-source-inline');if(!preview){preview=document.createElement('div');preview.className='ai-source-inline';article.append(preview);}if(preview.dataset.citation===selected.citation){preview.remove();return;}
    const full=selected.zh||selected.en,limit=selected.zh?100:280,excerpt=full.length>limit;preview.dataset.citation=selected.citation;
    preview.innerHTML='<details open><summary>'+escape(selected.citation)+' · '+escape(selected.title)+'</summary>'+(excerpt?'<small>原文节选 · 全文包含适用条件和例外</small>':'')+'<p'+(!selected.zh?' lang="en"':'')+'>'+escape(full.slice(0,limit))+(excerpt?'…':'')+'</p>'+(excerpt?'<small>以上为原文节选，请阅读全文核对条件和例外。</small>':'')+'<button data-ai-read-source="'+turn.id+'" data-ai-citation="'+escape(selected.citation)+'">阅读全文与相关条款 →</button></details>';preview.scrollIntoView({block:'nearest',behavior:'smooth'});return;
   }
   if(selected){const prefix=selected.doc==='core'?selected.ref.split('.').slice(0,2).join('.'):null;list=prefix?turn.sources.filter(s=>s.doc==='core'&&(s.ref===prefix||s.ref.startsWith(prefix+'.'))):[selected];}
   $('#ai-source-body').innerHTML=list.map(s=>'<article'+(s.citation===source.dataset.aiCitation?' class="ai-source-highlight"':'')+'><h3>'+escape(s.citation)+' · '+escape(s.title)+'</h3><p>'+escape(s.zh||s.en)+'</p>'+(s.zh&&s.en?'<details><summary>English 原文</summary><p lang="en">'+escape(s.en)+'</p></details>':'')+'<a href="'+escape(s.url)+'" target="_blank" rel="noopener noreferrer">来源 ↗</a></article>').join('');$('#ai-source-dialog').showModal();
  }
  const visual=event.target.closest('[data-ai-visual]');if(visual){const v=turns.get(visual.dataset.aiVisual)?.visuals.find(v=>v.id===visual.dataset.visualId);if(!v)return;$('#visual-title').textContent=v.title;$('#visual-subtitle').textContent=v.en;$('#visual-image').src=staticAsset(v.image);$('#visual-image').alt=v.title+' · WFDF 官方示意';$('#visual-description').textContent=v.description;$('#visual-source').href=v.source;$('#rule-visual-dialog').showModal();}
 });
 $('#ai-source-close').onclick=()=>$('#ai-source-dialog').close();
 fetch(endpoint('status'),{credentials:'same-origin'}).then(r=>r.json()).then(data=>{$$AIButtons(data.enabled);}).catch(()=>$$AIButtons(false));
 function $$AIButtons(enabled){aiAvailable=!!enabled;if(!aiAvailable&&creationMode==='ai')mode('manual');for(const id of ['ai-new-btn','ai-create-btn','ai-rules-btn']){$('#'+id).disabled=!enabled;$('#'+id).title=enabled?(id==='ai-rules-btn'?'AI 问规则 · DeepSeek':'DeepSeek'):'AI 暂未配置或连接不可用';}}
 return {openSetup,isAI:()=>creationMode==='ai',describe:()=>{page('description');$('#ai-tactic-result').textContent='';$('#ai-description').focus({preventScroll:true});}};
}
